bool balanced(String s) {
  const pairs = {')': '(', ']': '[', '}': '{'};
  final stack = <String>[];
  for (final c in s.split('')) {
    if ('([{'.contains(c)) {
      stack.add(c);
    } else if (pairs.containsKey(c)) {
      if (stack.isEmpty || stack.removeLast() != pairs[c]) return false;
    }
  }
  return stack.isEmpty;
}

void main() {
  print(balanced('{[]()}'));
  print(balanced('{[(])}'));
}
```

