int eval(List<String> tokens) {
  final s = <int>[];
  for (final t in tokens) {
    if (t == '-') {
      final b = s.removeLast();
      final a = s.removeLast();
      s.add(a - b);
    } else {
      s.add(int.parse(t));
    }
  }
  return s.single;
}

void main() {
  print(eval(['10', '3', '-']));
}
