int evalRpn(List<String> tokens) {
  final s = <int>[];
  for (final t in tokens) {
    switch (t) {
      case '+' || '*':
        final b = s.removeLast(), a = s.removeLast();
        s.add(t == '+' ? a + b : a * b);
      default:
        s.add(int.parse(t));
    }
  }
  return s.single;
}

void main() {
  print(evalRpn(['2', '3', '4', '*', '+']));
}
