List<int> nextGreater(List<int> a) {
  final res = List<int>.filled(a.length, -1);
  final s = <int>[];
  for (var i = 0; i < a.length; i++) {
    while (s.isNotEmpty && a[s.last] < a[i]) {
      res[s.removeLast()] = a[i];
    }
    s.add(i);
  }
  return res;
}

void main() {
  print(nextGreater([4, 5, 2, 25]));
}
