List<int> warmer(List<int> t) {
  final ans = List<int>.filled(t.length, 0);
  final s = <int>[];
  for (var d = 0; d < t.length; d++) {
    while (s.isNotEmpty && t[s.last] < t[d]) {
      final p = s.removeLast();
      ans[p] = d - p;
    }
    s.add(d);
  }
  return ans;
}

void main() {
  print(warmer([30, 40, 50, 60]));
}
